def nexty(key,col,used):
    ns=secs[key]['flow']['nodes']
    ys=[v[1] for v in ns.values() if v[0]==col]+used.get((key,col),[])
    y=(max(ys)+84) if ys else 40
    used.setdefault((key,col),[]).append(y); return y
